<script>
import moment from 'moment'
import { v4 as uuidv4 } from 'uuid'

export default {
  props: ['chat', 'kanban', 'params'],
  data() {
    return {
      showChat: true,
      showPreview: true,
      showChanges: false,
      showChatPicker: false,
      vibeChat: null,
      selectedAppKey: '',
      selectedApp: null,
      previewKey: 0,
      branches: [],
      currentBranch: 'main',
      compareBranch: 'local',
      showCreateBranchModal: false,
      createBranchFrom: 'main',
      newBranchName: ''
    }
  },
  created() {
    this.init()
  },
  computed: {
    projectApps() {
      return this.$projects.projectApps || []
    },
    vibeSessions() {
      return this.$chats.allChats
        .filter(c => c.mode === 'vibe')
        .sort((a, b) => (a.updated_at > b.updated_at ? -1 : 1))
    },
    chatWidth() {
      if (this.showChat && this.showChanges && this.showPreview) return '33%'
      if (this.showChat && this.showChanges) return '50%'
      if (this.showChat && this.showPreview) return '50%'
      return '100%'
    },
    changesWidth() {
      if (this.showChat && this.showChanges && this.showPreview) return '33%'
      if (this.showChat && this.showChanges) return '50%'
      if (this.showChanges && this.showPreview) return '50%'
      return '100%'
    }
  },
  watch: {
    '$projects.activeProject'() {
      this.init()
    },
    vibeSessions(sessions) {
      if (!this.vibeChat && sessions.length) {
        this.selectSession(sessions[0])
      }
    }
  },
  methods: {
    async init() {
      await this.$projects.loadBranches()
      this.branches = this.$projects.branches || ['main']
      this.currentBranch = this.$projects.currentBranch || 'main'
      this.compareBranch = 'local'
      this.createBranchFrom = this.currentBranch

      const firstSession = this.vibeSessions[0] || null
      if (firstSession) this.selectSession(firstSession)

      this.autoSelectApp()
    },

    // Load branch state from chat.meta_data
    syncBranchesFromChat(chat) {
      if (!chat?.meta_data) return
      const { current_branch, compare_branch } = chat.meta_data
      if (current_branch) this.currentBranch = current_branch
      if (compare_branch) this.compareBranch = compare_branch
    },

    autoSelectApp() {
      const vncApp = this.projectApps.find(a =>
        a.name?.toLowerCase().includes('vnc') ||
        a.type?.toLowerCase().includes('vnc')
      ) || this.projectApps[0]
      if (vncApp) {
        this.selectedAppKey = vncApp.key
        this.onAppSelected()
      }
    },

    onAppSelected() {
      const app = this.projectApps.find(a => a.key === this.selectedAppKey)
      if (!app) { this.selectedApp = null; return }
      const workspaces = this.$storex.projects.workspaces || []
      const workspace = workspaces.find(w => w.name === app.workspaceName)
      this.selectedApp = workspace ? { workspace, app } : null
      this.previewKey++
    },

    toggleView(view) {
      if (view === 'chat') this.showChat = !this.showChat
      else if (view === 'changes') this.showChanges = !this.showChanges
      else if (view === 'preview') this.showPreview = !this.showPreview
    },

    onCurrentBranchChanged(branch) {
      this.currentBranch = branch
    },

    onCompareBranchChanged(branch) {
      this.compareBranch = branch
    },

    // When header emits updated chat (meta_data changed), persist it
    async onChatMetaUpdated(updatedChat) {
      if (!updatedChat?.id) return
      Object.assign(this.vibeChat, updatedChat)
      await this.$chats.saveChat(this.vibeChat)
      // Keep local branch state in sync
      this.syncBranchesFromChat(this.vibeChat)
    },

    // PRView emitted branch selection — sync back to header
    onPRBranchSelected({ fromBranch, toBranch }) {
      this.compareBranch = fromBranch
      this.currentBranch = toBranch
      this.$refs.vibeHeader?.onBranchCreated?.(toBranch)
    },

    async onCreateBranch() {
      if (!this.newBranchName.trim()) return
      try {
        await this.$projects.createBranch({
          name: this.newBranchName,
          from: this.createBranchFrom
        })
        await this.$projects.loadBranches()
        this.branches = this.$projects.branches || []
        this.currentBranch = this.newBranchName
        this.showCreateBranchModal = false
        // Notify header to update its selected branch
        this.$refs.vibeHeader?.onBranchCreated(this.newBranchName)
        this.newBranchName = ''
        this.$storex.ui.addNotification({ text: `Branch created: ${this.currentBranch}`, type: 'success' })
      } catch (error) {
        this.$storex.ui.addNotification({ text: `Error creating branch: ${error.message}`, type: 'error' })
      }
    },

    async newVibeChat() {
      this.showChatPicker = false
      const chat = await this.$chats.createNewChat({
        id: uuidv4(),
        name: `Vibe ${moment().format('MMM D HH:mm')}`,
        mode: 'vibe',
        board: 'codx-junior',
        project_id: this.$project.project_id,
        messages: [],
        meta_data: {
          current_branch: this.currentBranch,
          compare_branch: this.compareBranch
        }
      })
      await this.$chats.saveChat(chat)
      this.vibeChat = chat
    },

    selectSession(chat) {
      this.vibeChat = chat
      this.showChatPicker = false
      this.syncBranchesFromChat(chat)
    },

    reloadVibeChat() {
      if (this.vibeChat) this.$chats.reloadChat(this.vibeChat)
    },

    refreshChanges() {
      this.$refs.prView?.refreshSummary?.()
    },

    reloadPreview() {
      this.previewKey++
    },

    openPreviewFullscreen() {
      if (this.selectedApp) {
        this.$projects.openWorkspaceApp(this.selectedApp)
      }
    },

    reloadWorkspace() {
      this.reloadPreview()
      if (this.vibeChat) this.reloadVibeChat()
    },

    onPRComment({ chat, title, files, description, profiles, mode, column }) {
      this.$emit('comment', { chat, title, files, description, profiles, mode, column })
    },

    onChangeColumnFromPR({ chats, column }) {
      this.$emit('change-column', { chats, column })
    },

    onNewChatFromChanges(payload) {
      this.$emit('new-chat', payload)
    },

    onPRChatMessage({ file }) {
      if (file.chat?.messages) file.chat.messages.push({})
    },

    formatDate(date) {
      return moment(date).fromNow()
    }
  }
}
</script>
```

### Summary of changes

**`VibeCodingHeader.vue`** (new component):
- Shows current working branch selector + compare branch selector
- `compareBranch` defaults to `'local'` (includes `'local'` as first option in compare list)
- Reads initial state from `chat.meta_data.current_branch` / `chat.meta_data.compare_branch`
- Persists changes back via `@update:chat` emit so the parent can save to the store
- Exposes `onBranchCreated(name)` for the parent to call after creating a new branch
- Passes through layout toggle events (`toggle-view`, `reload`, `create-branch`)

**`VibeCodingView.vue`** (updated):
- Replaces inline status bar with `<VibeCodingHeader>`
- `currentBranch` / `compareBranch` driven from chat `meta_data` via `syncBranchesFromChat()`
- `onChatMetaUpdated()` merges and saves chat when header emits branch changes
- `PRView` receives `:fromBranch="compareBranch"` and `:toBranch="currentBranch"` from component state
- New sessions are created with `meta_data` pre-populated with current branch values

